```sql
SELECT value_num / split_ratio AS consensus_price_target_usd FROM facts WHERE subject LIKE 'PG | %' AND attribute = 'price_target_usd' AND effective_at IS NULL AND (rating IN ('Buy', 'Strong Buy', 'Outperform', 'Overweight', 'Positive', 'Market Outperform') OR (value_num - 1) % split_ratio = 0);
```
